print(f"Total raw items collected: {len(data)}")

# Let's generate TS code
ts_lines = ["import { RawMCQ } from './questionsData';\n", "export const BATCH_PREPOSITIONS: RawMCQ[] = ["]

start_id = 1529
for i, item in enumerate(data):
    q_id = start_id + i
    q_text, target, options, ans, meaning, exp, exam = item
    obj = {
        "id": q_id,
        "question": q_text,
        "targetWord": target,
        "type": "preposition",
        "category": "Prepositions",
        "examTag": exam,
        "options": options,
        "correctAnswer": ans,
        "wordMeaningBangla": meaning,
        "explanationBangla": exp
    }
    ts_lines.append("  " + json.dumps(obj, ensure_ascii=False) + ",")

ts_lines.append("];\n")

target_file = "/src/data/questionsPrepositions.ts"
with open(target_file, "w", encoding="utf-8") as f:
    f.write("\n".join(ts_lines))

print(f"Successfully generated {len(data)} preposition questions in {target_file} from ID {start_id} to {start_id + len(data) - 1}")
